function [fbk_out, ref_out] = mfun_olvhz_vhz_controller(w_M, meas_in, u_c_ab_in, u_c_zoh_ab_in, p)
%MFUN_OLVHZ_VHZ_CONTROLLER Block OpenLoopVHzController of the control system.
%   OpenLoopVHzController of motulator. Generated by motulator_export from the MATLAB
%   port of motulator; the MATLAB Function block of a model calls this function, copied
%   into the folder of the model. The parameters are the fields of the struct p, the
%   struct of the block in the struct ctrl_par of the parameters of the blocks of its
%   control system (e.g., ctrl_par.SpeedController, see the function of the parameters
%   of the control system, e.g., fvc_params; [] as NaN). The state is in persistent
%   variables, of which each MATLAB Function block has its own copy.
persistent self
if isempty(self)
    self = im_open_loop_vhz_ctrl_init(p.n_p, ...
        complex(p.u_s_ref_u_0(1), p.u_s_ref_u_0(2)), ...
        complex(p.u_s_ref_k(1), p.u_s_ref_k(2)), p.T_s);
end
meas = im_open_loop_vhz_measurements_unpack(meas_in);
u_c_ab = complex_in(u_c_ab_in);
u_c_zoh_ab = complex_in(u_c_zoh_ab_in);
fbk = im_open_loop_vhz_ctrl_get_feedback(self, u_c_zoh_ab, meas.i_c_ab, w_M);
% Voltage for the control laws (DriveControlSystem.get_feedback), or
% u_s_zoh if unknown
if isnan(real(u_c_ab))
    fbk.u_s = fbk.u_s_zoh;
else
    fbk.u_s = exp(-1i*fbk.theta_c)*u_c_ab;
end
ref = struct('u_s', im_open_loop_vhz_ctrl_compute_output(self, fbk));
fbk_out = im_open_loop_vhz_feedbacks_pack(fbk);
ref_out = im_open_loop_vhz_references_pack(ref);
self = im_open_loop_vhz_ctrl_update(self, p.T_s, fbk);
end

function s = im_open_loop_vhz_measurements_unpack(u)
%IM_OPEN_LOOP_VHZ_MEASUREMENTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c_ab', complex(u(1), u(2)), ...
    'u_dc', u(3));
end

function y = im_open_loop_vhz_feedbacks_pack(s)
%IM_OPEN_LOOP_VHZ_FEEDBACKS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_s);
    imag(s.i_s);
    real(s.u_s);
    imag(s.u_s);
    real(s.u_s_zoh);
    imag(s.u_s_zoh);
    s.w_M;
    s.w_s;
    s.w_c;
    s.theta_c];
end

function y = im_open_loop_vhz_references_pack(s)
%IM_OPEN_LOOP_VHZ_REFERENCES_PACK Signal vector of the struct s.
y = [ ...
    real(s.u_s);
    imag(s.u_s)];
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function theta = wrap(theta)
%WRAP Limit the angle into the range [-pi, pi), as numpy.mod does.
x = rem(theta + pi, 2*pi);
if x < 0
    x = x + 2*pi;
end
theta = x - pi;
end

function self = im_open_loop_vhz_ctrl_init(n_p, u_0, k, T_s)
%IM_OPEN_LOOP_VHZ_CTRL_INIT Open-loop V/Hz controller (OpenLoopVHzController).
self = struct('n_p', n_p, 'u_0', complex(u_0), 'k', complex(k), 'T_s', T_s, ...
    'theta_c', 0);
end

function fbk = im_open_loop_vhz_ctrl_get_feedback(self, u_s_ab, i_s_ab, w_M_ref)
%IM_OPEN_LOOP_VHZ_CTRL_GET_FEEDBACK Feedback signals (OpenLoopVHzFeedbacks) without
%   u_dc and u_s, the voltage u_s_ab NaN if unknown (blocked gates).
theta_c = self.theta_c;
w_s = self.n_p*w_M_ref;
u_s_zoh = complex(0);
if ~isnan(real(u_s_ab))
    u_s_zoh = exp(-1i*theta_c)*u_s_ab;
end
fbk = struct('i_s', exp(-1i*theta_c)*i_s_ab, 'u_s', complex(0), ...
    'u_s_zoh', u_s_zoh, 'w_M', w_M_ref, 'w_s', w_s, 'w_c', w_s, ...
    'theta_c', theta_c);
end

function u_s_ref = im_open_loop_vhz_ctrl_compute_output(self, fbk)
%IM_OPEN_LOOP_VHZ_CTRL_COMPUTE_OUTPUT Stator voltage reference from the V/Hz curve.
u_s_ref = self.u_0 + self.k*fbk.w_s;
end

function self = im_open_loop_vhz_ctrl_update(self, T_s, fbk)
%IM_OPEN_LOOP_VHZ_CTRL_UPDATE Update the angle of the coordinate system.
self.theta_c = wrap(self.theta_c + T_s*fbk.w_c);
end
